const remH=()=>rem().map(f=>{const n=dd(f.tempo,today()),nm=esc(f.dist)+(f.no?' No. '+esc(f.no):''),sisa=`sisa <b>${rp(sisaF(f))}</b>`;
if(n>0)return`<div class=card style="border-color:var(--w);cursor:pointer" onclick="pickF('${f.id}')">🔔 <b>Reminder H-${n}:</b> nota ${nm} jatuh tempo ${f.tempo}, ${sisa}</div>`;
const L=n==0?'Reminder H+0: nota '+nm+' jatuh tempo HARI INI':'Reminder H+'+(-n)+': nota '+nm+' TERLAMBAT '+(-n)+' hari (tempo '+f.tempo+')';
return`<div class=card style="border-color:var(--bad);color:var(--bad);font-weight:700;cursor:pointer" onclick="pickF('${f.id}')">🔔 ${L}, ${sisa}</div>`}).join('');
