async function dl(n,t,m,share){const C=window.Capacitor,P=C&&C.Plugins;
if(C&&C.isNativePlatform&&C.isNativePlatform()){
if(!share&&P&&P.SaveFile){try{await P.SaveFile.save({name:n,mime:m,data:t});toast('Tersimpan: '+n);return true}catch(e){if(/cancel/i.test(e.message||e.errorMessage||''))return false;toast('Dialog simpan gagal, beralih ke Bagikan')}}
if(!(P&&P.Filesystem&&P.Share)){toast('Fitur simpan file tidak tersedia di aplikasi ini');return false}
try{const r=await P.Filesystem.writeFile({path:n,data:t,directory:'CACHE',encoding:'utf8'});await P.Share.share({title:n,url:r.uri,dialogTitle:'Bagikan '+n});return true}catch(e){if(!/cancel/i.test(e.message||''))toast('Gagal menyimpan: '+(e.message||e));return false}}
try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:m}));a.download=n;document.body.append(a);a.click();a.remove();return true}catch(e){toast('Gagal mengunduh: '+e.message);return false}}
const expJ=async(share)=>{if(await dl('kelontong-backup-'+today()+'.json',JSON.stringify({app:'kelontong2080',v:1,data:D}),'application/json',share===true)){localStorage.lastBackup=today();render()}};
