const fk=v=>v>=1e9?(v/1e9).toFixed(1)+' M':v>=1e6?(v/1e6).toFixed(1)+' jt':Math.round(v/1e3)+' rb';
const mcS=()=>(D.set.find(x=>x.id=='mc')||{}).v,tAvg=x=>(x.qmin+x.qmax)/2,tMg=x=>x.jual-x.hpp;
const MCC={'Fast moving':'#4cc38a','Prinsip 20/80':'#d4af37','Untung per item':'#5aa9ff','Merata (pembanding)':'#9aa8a0','Hemat modal':'#c084fc'};
function mc(){const S0=mcS();if(!S0)return null;const it=D.target.filter(x=>x.st=='ada'&&tMg(x)>0&&x.qmax>0);if(!it.length)return null;
let sd=12345;const rnd=()=>{sd=(sd*1664525+1013904223)>>>0;return sd/4294967296},W=S0.minggu,step=Math.max(1,Math.ceil(S0.putaran/7)),N=300,nm=w=>{const t=sum(w);return w.map(v=>v/t)};
const sr=[...it].sort((a,b)=>tAvg(b)*tMg(b)-tAvg(a)*tMg(a)),k=Math.max(1,Math.round(it.length*.2));
const st={'Fast moving':nm(it.map(tAvg)),'Prinsip 20/80':nm(it.map(x=>sr.indexOf(x)<k?.8/k:.2/Math.max(1,it.length-k))),'Untung per item':nm(it.map(tMg)),'Merata (pembanding)':nm(it.map(()=>1)),'Hemat modal':null},ef=[...it].sort((a,b)=>tMg(b)/b.hpp-tMg(a)/a.hpp);
const q=(a,p)=>{const z=[...a].sort((x,y)=>x-y);return z[Math.floor(p*(z.length-1))]},res={};
for(const n in st){const w=st[n],out=Array.from({length:W+1},()=>[]),hit=[];
for(let r=0;r<N;r++){let M=S0.modal,h=null;out[0].push(M);for(let t=1;t<=W;t++){if(t%step==0){let p=0,hm=null;if(!w){hm=it.map(()=>0);let rem=M;for(const cp of[tAvg,x=>x.qmax])for(const x of ef){const i=it.indexOf(x),u=Math.min(Math.max(0,cp(x)*step-hm[i]),rem/x.hpp);hm[i]+=u;rem-=u*x.hpp}}it.forEach((x,i)=>{p+=Math.min((x.qmin+rnd()*(x.qmax-x.qmin))*step,w?w[i]*M/x.hpp:hm[i])*tMg(x)});M+=p}out[t].push(M);if(h==null&&S0.tujuan>0&&M>=S0.tujuan)h=t}hit.push(h)}
const hh=hit.filter(x=>x!=null);res[n]={p50:out.map(a=>q(a,.5)),p10:q(out[W],.1),p90:q(out[W],.9),pct:Math.round(hh.length/N*100),wk:hh.length>=N/2?q(hh,.5):null}}
return{W,res,it,step,st,ef}}
const alloc=(r,n,M)=>{const{it,step,st,ef}=r,w=st[n];if(w)return{u:it.map((x,i)=>w[i]*M/x.hpp),rem:0};const u=it.map(()=>0);let rem=M;for(const cp of[tAvg,x=>x.qmax])for(const x of ef){const i=it.indexOf(x),a=Math.min(Math.max(0,cp(x)*step-u[i]),rem/x.hpp);u[i]+=a;rem-=a*x.hpp}return{u,rem}};
const recH=(r,S0,best)=>{const W=r.W,h=Math.round(W/2),ph=[['Tahap 1 — modal awal',S0.modal],['Tahap 2 — modal ≈ '+rp(r.res[best].p50[h])+' (minggu '+h+')',r.res[best].p50[h]]],A=ph.map(p=>alloc(r,best,p[1])),fx=!!r.st[best];
const pc=(a,M,i)=>Math.round(a.u[i]*r.it[i].hpp/M*100),ord=r.it.map((x,i)=>i).sort((a,b)=>A[0].u[b]*r.it[b].hpp-A[0].u[a]*r.it[a].hpp);
const lb=(a,M)=>sum(r.it.map((x,i)=>Math.min(tAvg(x)*r.step,a.u[i])*tMg(x)));
return`<div class=card style="border-color:var(--g)"><h3>Rekomendasi pembagian modal — skema ${best}</h3>`+ph.map((p,k)=>`<div style="margin:10px 0"><b>${p[0]}</b><div class=m>Laba kotor perkiraan per putaran ≈ ${rp(lb(A[k]))} (${(lb(A[k])/p[1]*100).toFixed(0)}% dari modal)</div>`+ord.map(i=>{const x=r.it[i],a=A[k],v=a.u[i]*x.hpp;return`<div class="row sp" style="margin:4px 0"><span>${esc(x.nama)}</span><span class=m style="text-align:right">${pc(a,p[1],i)}% • ${rp(v)} • ±${Math.round(a.u[i])} unit</span></div>`}).join('')+(A[k].rem>1?`<div class="row sp m"><span>Belum terpakai</span><span>${Math.round(A[k].rem/p[1]*100)}% • ${rp(A[k].rem)} (permintaan sudah terpenuhi)</span></div>`:'')+'</div>').join('')+`<div class=m>${fx?'Skema ini memakai pembagian tetap, jadi persentasenya sama di semua tahap.':'Isi barang paling efisien dulu sampai kebutuhan satu putarannya terpenuhi, baru ke barang berikutnya. Saat modal naik, tambah alokasi mengikuti urutan itu.'} Beli sejumlah unit di atas tiap putaran. Jika sebuah barang habis lebih cepat dari putaran, tambah alokasinya dari modal yang belum terpakai.</div></div>`};
const mcH=()=>{const S0=mcS(),head=`<div class=card><div class="row sp"><h3 style="margin:0">Simulasi Monte Carlo — akumulasi modal</h3><button class=g style="min-height:36px;flex:0 0 auto" onclick="setMC()">Atur simulasi</button></div>`,r=mc();
if(!r)return head+'<div class=m style="margin-top:8px">Data belum cukup. Tekan Atur simulasi (isi modal awal) dan tambahkan minimal 1 barang target berstatus Tersedia dengan harga jual di atas harga beli.</div></div>';
const nm=Object.keys(r.res),all=nm.flatMap(n=>r.res[n].p50),y0=Math.min(...all),y1=Math.max(...all),W=r.W,X=i=>40+i/W*290,Y=v=>170-(v-y0)/((y1-y0)||1)*150;
const ln=nm.map(n=>`<polyline fill=none stroke="${MCC[n]}" stroke-width=2 ${n[0]=='M'?'stroke-dasharray="4 3"':''} points="${r.res[n].p50.map((v,i)=>X(i).toFixed(1)+','+Y(v).toFixed(1)).join(' ')}"/>`).join('');
const gy=[0,.5,1].map(f=>{const v=y0+(y1-y0)*f;return`<line x1=40 x2=330 y1=${Y(v)} y2=${Y(v)} stroke="#ffffff1a"/><text x=36 y=${Y(v)+4} text-anchor=end font-size=10 fill="#9aa8a0">${fk(v)}</text>`}).join('');
const gx=[0,.5,1].map(f=>`<text x=${X(W*f)} y=190 text-anchor=middle font-size=10 fill="#9aa8a0">mgg ${Math.round(W*f)}</text>`).join('');
const best=nm.reduce((a,n)=>r.res[n].p50[W]>r.res[a].p50[W]?n:a,nm[0]);
return head+`<svg viewBox="0 0 340 196" style="width:100%;margin-top:8px">${gy}${gx}${ln}</svg>`+nm.map(n=>{const o=r.res[n];return`<div style="margin:8px 0"><span style="color:${MCC[n]}">●</span> <b>${n}</b>${n==best?' <span class="b h">tertinggi</span>':''}<div class=m>Median akhir ${rp(o.p50[W])} • P10–P90: ${rp(o.p10)} – ${rp(o.p90)}${S0.tujuan>0?` • Target ${rp(S0.tujuan)}: ${o.wk?'minggu ke-'+o.wk+' ('+o.pct+'% simulasi)':'belum tercapai ('+o.pct+'% simulasi)'}`:''}</div></div>`}).join('')+recH(r,S0,best)+'<div class=m>Simulasi 300 kali dari perkiraan terjual min–max yang kamu isi. Laba kotor diputar ulang sebagai modal, tanpa biaya operasional, kerugian kedaluwarsa, atau perubahan harga. Ini bukan ramalan.</div></div>'};
const tgH=()=>`<h2 class=sec>Target barang 20/80</h2><button style="width:100%" onclick="addT()">+ Tambah Barang Target</button>`+(D.target.map(x=>`<div class=card><div class="row sp"><b>${esc(x.nama)}</b><span class="b ${x.st=='ada'?'h':'r'}">${x.st=='ada'?'Tersedia':'Tidak tersedia'}</span></div><div class=m>Beli ${rp(x.hpp)} • Jual ${rp(x.jual)} • Untung ${rp(tMg(x))}/unit (${x.jual>0?(tMg(x)/x.jual*100).toFixed(1):0}%)<br>Perkiraan terjual ${x.qmin}–${x.qmax}/minggu</div><div class=row style="margin-top:8px"><button class=g onclick="togT('${x.id}')">Ubah ketersediaan</button><button class=d onclick="del2('target','${x.id}')">Hapus</button></div></div>`).join('')||'<div class=e>Belum ada barang target.</div>');
const efH=()=>{const on=D.target.filter(x=>x.st=='ada'&&tMg(x)>0&&x.hpp>0);if(!on.length)return'';const E=x=>tMg(x)/x.hpp,ef=[...on].sort((a,b)=>E(b)-E(a)),mod=x=>tAvg(x)*x.hpp,lab=x=>tAvg(x)*tMg(x),TL=sum(ef.map(lab)),TM=sum(ef.map(mod));let cm=0,cl=0;
const rows=ef.map(x=>{cm+=mod(x);cl+=lab(x);return{x,cm,cl}});
const th=[.5,.8,1].map(p=>{const r=rows.find(q=>q.cl/TL>=p-1e-9);return`<div style="margin:6px 0">${Math.round(p*100)}% laba: modal ≈ <b>${rp(r.cm)}</b> (${Math.round(r.cm/TM*100)}% modal total) — ${rows.slice(0,rows.indexOf(r)+1).map(q=>esc(q.x.nama)).join(', ')}</div>`}).join('');
return`<h2 class=sec>Efisiensi modal</h2><div class=card><h3>Laba per Rp modal (per putaran), dari yang paling efisien</h3>`+rows.map((r,i)=>`<div style="margin:8px 0"><b>${i+1}. ${esc(r.x.nama)}</b> <span class="b h">${(E(r.x)*100).toFixed(0)}%</span><div class=m>Modal ${rp(mod(r.x))}/mgg • laba ${rp(lab(r.x))}/mgg • kumulatif: modal ${rp(r.cm)}, laba ${Math.round(r.cl/TL*100)}%</div></div>`).join('')+`</div><div class=card><h3>Modal minimum untuk meraih laba</h3>${th}</div><div class=m>Dari rata-rata perkiraan terjual min–max, modal diputar mingguan. Barang efisiensi rendah bisa tetap penting untuk menjaga pelanggan.</div>`};
const advH=()=>{const L=D.target.filter(x=>tMg(x)>0),on=L.filter(x=>x.st=='ada'),c=x=>tAvg(x)*tMg(x),tot=sum(on.map(c)),a=[];if(!L.length)return'';
[...on].sort((p,q)=>c(q)-c(p)).slice(0,Math.max(1,Math.round(on.length*.2))).forEach(x=>a.push(`Prioritaskan <b>${esc(x.nama)}</b>: ≈ ${rp(c(x))} laba kotor/minggu (${tot?Math.round(c(x)/tot*100):0}% dari total target tersedia). Pastikan stoknya selalu ada.`));
L.filter(x=>x.st!='ada').forEach(x=>a.push(`<b>${esc(x.nama)}</b> tidak tersedia: potensi laba kotor ≈ ${rp(c(x))}/minggu belum terambil. Tantangan: cari distributor atau stok alternatif.`));
on.filter(x=>tMg(x)/x.jual<.1).forEach(x=>a.push(`<b>${esc(x.nama)}</b> margin tipis (${(tMg(x)/x.jual*100).toFixed(1)}%). Tantangan: tawar harga beli atau tinjau harga jual.`));
const md=l=>l.sort((p,q)=>p-q)[Math.floor(l.length/2)]||0,mm=md(on.map(x=>tMg(x)/x.jual)),vv=md(on.map(tAvg));
on.filter(x=>tMg(x)/x.jual>mm&&tAvg(x)<vv).forEach(x=>a.push(`<b>${esc(x.nama)}</b> margin tinggi tapi volume rendah. Ide: tawarkan sebagai paket atau taruh di tempat yang mudah terlihat.`));
const top=[...on].sort((p,q)=>c(q)-c(p))[0];if(top&&on.length>1&&tot&&c(top)/tot>.5)a.push(`Ketergantungan tinggi pada <b>${esc(top.nama)}</b> (${Math.round(c(top)/tot*100)}% laba target). Jika stok kosong, laba turun drastis.`);
return`<h2 class=sec>Nasehat, ide, dan tantangan</h2>`+(a.map(t=>`<div class=card>${t}</div>`).join('')||'<div class=e>Belum ada saran.</div>')};
const addT=()=>form('Barang Target',[['nama','Nama barang','text','required'],['hpp','Harga beli/unit (Rp)','rp',''],['jual','Harga jual/unit (Rp)','rp',''],['qmin','Perkiraan terjual/minggu — minimum','number','min=0 required'],['qmax','Perkiraan terjual/minggu — maksimum','number','min=0 required'],['st','Ketersediaan','select',[['ada','Tersedia'],['tidak','Tidak tersedia']]]],v=>{if(+v.qmax<+v.qmin)throw Error('Maksimum harus ≥ minimum');return save([['put','target',{id:uid(),nama:v.nama.trim(),hpp:v.hpp,jual:v.jual,qmin:+v.qmin,qmax:+v.qmax,st:v.st}]])});
const togT=id=>{const x=D.target.find(t=>t.id==id);save([['put','target',{...x,st:x.st=='ada'?'tidak':'ada'}]]).catch(e=>toast(e.message))};
const setMC=()=>{const s=mcS()||{};form('Atur simulasi',[['modal','Modal awal (Rp)','rp','',s.modal],['minggu','Lama simulasi (minggu)','number','min=4 max=104 required value='+(s.minggu||26)],['putaran','Putaran modal (hari sampai modal kembali)','number','min=1 max=60 required value='+(s.putaran||7)],['tujuan','Target modal (Rp, isi 0 jika tidak ada)','rp','z',s.tujuan]],v=>save([['put','set',{id:'mc',v:{modal:v.modal,minggu:+v.minggu,putaran:+v.putaran,tujuan:v.tujuan}}]]))};
const ide0=V.ide;V.ide=()=>mcH()+tgH()+efH()+advH()+ide0();
const sb=document.createElement('div');sb.id='sb';sb.innerHTML='<i></i>';document.body.append(sb);
function sbU(){const h=document.documentElement,mx=h.scrollHeight-innerHeight;sb.style.display=mx>60?'block':'none';const tr=sb.clientHeight,th=Math.max(44,tr*innerHeight/h.scrollHeight);sb.firstChild.style.height=th+'px';sb.firstChild.style.top=(mx>0?scrollY/mx*(tr-th):0)+'px'}
function sbM(e){const r=sb.getBoundingClientRect(),th=sb.firstChild.offsetHeight,p=Math.min(1,Math.max(0,(e.clientY-r.top-th/2)/(r.height-th)));scrollTo(0,p*(document.documentElement.scrollHeight-innerHeight))}
addEventListener('scroll',sbU,{passive:true});addEventListener('resize',sbU);
sb.addEventListener('pointerdown',e=>{sb.setPointerCapture(e.pointerId);sbM(e)});sb.addEventListener('pointermove',e=>{if(sb.hasPointerCapture(e.pointerId))sbM(e)});

/* ===== Tab CARI: daftar barang yang perlu dicari/disediakan ===== */
const CS={belum:'Belum dicari',proses:'Dalam proses',done:'Sudah ada'},CB={belum:'r',proses:'y',done:'h'};let cf='aktif';
const cariN=()=>(D.cari||[]).filter(x=>x.status!='done').length;
V.cari=()=>{const L=D.cari||[],c=k=>L.filter(x=>x.status==k).length,F=[['aktif','Belum selesai ('+cariN()+')'],['belum','Belum ('+c('belum')+')'],['proses','Proses ('+c('proses')+')'],['done','Ada ('+c('done')+')'],['semua','Semua ('+L.length+')']],
o={belum:0,proses:1,done:2},r=L.filter(x=>cf=='semua'||(cf=='aktif'?x.status!='done':x.status==cf)).sort((a,b)=>o[a.status]-o[b.status]||(a.dibuat<b.dibuat?1:-1));
return`<button style="width:100%" onclick="addC()">+ Tambah Barang yang Dicari</button><div class=row style="margin-top:10px;gap:6px">`+F.map(f=>`<button class="${cf==f[0]?'':'g'}" style="font-size:12px;padding:0 6px;min-height:36px" onclick="cfS('${f[0]}')">${f[1]}</button>`).join('')+`</div>`+
(r.map(x=>`<div class=card><div class="row sp"><b>${esc(x.nama)}</b><span class="b ${CB[x.status]}" style="flex:none">${CS[x.status]}</span></div><div class=m>${x.jml?'Butuh: '+esc(x.jml)+' • ':''}Dicatat ${x.tgl}${x.tglDone?' • Ada sejak '+x.tglDone:''}</div>${x.cat?`<div class=m style="margin-top:2px">${esc(x.cat)}</div>`:''}<div class=row style="margin-top:8px;gap:6px">`+Object.entries(CS).map(([k,l])=>`<button class="${x.status==k?'':'g'}" style="font-size:12px;padding:0 4px" onclick="stC('${x.id}','${k}')">${l}</button>`).join('')+`</div><div class=row style="margin-top:6px"><button class=g onclick="edC('${x.id}')">Ubah</button><button class=d onclick="delC('${x.id}')">Hapus</button></div></div>`).join('')||'<div class=e>'+(L.length?'Tidak ada barang di filter ini.':'Belum ada barang yang dicari. Catat barang yang kosong dari sales di sini.')+'</div>')};
const cfS=k=>{cf=k;render()};
const addC=()=>form('Barang yang Dicari',[['nama','Nama barang','text','required'],['jml','Butuh berapa (opsional)','text','placeholder="mis. 2 dus"'],['cat','Catatan (opsional)','text','placeholder="mis. sales kosong, coba toko grosir"'],['status','Status','select',Object.entries(CS)]],v=>save([['put','cari',{id:uid(),nama:v.nama.trim(),jml:v.jml.trim(),cat:v.cat.trim(),status:v.status,tgl:today(),tglDone:v.status=='done'?today():'',dibuat:new Date().toISOString()}]]));
const edC=id=>{const x=D.cari.find(e=>e.id==id);form('Ubah Barang',[['nama','Nama barang','text','required value="'+esc(x.nama)+'"'],['jml','Butuh berapa (opsional)','text','value="'+esc(x.jml)+'"'],['cat','Catatan (opsional)','text','value="'+esc(x.cat)+'"']],v=>save([['put','cari',{...x,nama:v.nama.trim(),jml:v.jml.trim(),cat:v.cat.trim()}]]))};
const stC=(id,st)=>{const x=D.cari.find(e=>e.id==id);if(!x||x.status==st)return;save([['put','cari',{...x,status:st,tglDone:st=='done'?today():''}]]).catch(e=>toast('Gagal: '+e.message))};
const delC=id=>confirm('Hapus barang ini dari daftar cari?')&&save([['delete','cari',id]]).catch(e=>toast('Gagal: '+e.message));

/* ===== Notifikasi lokal Android (jalan walau layar mati / app ditutup) ===== */
const LN=()=>{const C=window.Capacitor,P=C&&C.Plugins;return C&&C.isNativePlatform&&C.isNativePlatform()&&P&&P.LocalNotifications||null};
const nid=t=>{let h=7;for(const c of t)h=(h*31+c.charCodeAt(0))|0;return Math.abs(h)%2000000000};
async function nReady(ask){const n=LN();if(!n)return false;try{await n.createChannel({id:'nota',name:'Reminder nota',description:'Pengingat nota sales jatuh tempo',importance:4,visibility:1,vibration:true})}catch(e){}
let p=await n.checkPermissions();if(p.display!='granted'&&ask)p=await n.requestPermissions();return p.display=='granted'}
const nCfg=()=>{let t=localStorage.nTime||'08:00';if(!/^\d\d:\d\d$/.test(t))t='08:00';return{on:localStorage.nOn!='0',t,h:+t.slice(0,2),m:+t.slice(3)}};
async function nSetT(v){if(!/^\d\d:\d\d$/.test(v))return toast('Jam tidak valid');localStorage.nTime=v;await schedN(true,true);render();toast('Jam reminder diubah ke '+v.replace(':','.'))}
async function nTog(){const on=!nCfg().on;localStorage.nOn=on?'1':'0';await schedN(true,true);render();toast(on?'Reminder otomatis AKTIF':'Reminder otomatis DIMATIKAN')}
let nRun=0,nQ=0;
async function schedN(ask,force){if(nRun){nQ=1;return}nRun=1;try{await schedN0(ask,force)}finally{nRun=0}if(nQ){nQ=0;return schedN(false,force)}}
async function schedN0(ask,force){if(!force&&localStorage.nSafe=='1')return;try{if(!await nReady(ask))return;const n=LN();localStorage.nBusy='1';
let pend=[];try{pend=((await n.getPending()).notifications||[]).map(x=>x.id)}catch(e){}
for(let i=0;i<pend.length;i+=40)await n.cancel({notifications:pend.slice(i,i+40).map(id=>({id}))});
const C=nCfg(),now=Date.now(),L=[],act=C.on?D.faktur.filter(f=>sisaF(f)>0):[];
act.forEach(f=>{for(let k=2;k>=-30;k--){const[y,m,d]=f.tempo.split('-').map(Number),at=new Date(y,m-1,d-k,C.h,C.m,0);if(at<=now)continue;L.push({id:nid(f.id+'|'+k),channelId:'nota',smallIcon:'ic_stat_kelontong',title:k>0?`Nota ${f.dist} jatuh tempo ${k==1?'besok':'2 hari lagi'}`:k==0?`H+0: Nota ${f.dist} jatuh tempo HARI INI`:`TERLAMBAT H+${-k}: Nota ${f.dist} belum dibayar`,body:`${f.no?'No. '+f.no+' • ':''}Sisa ${rp(sisaF(f))} • Tempo ${f.tempo}`,autoCancel:false,extra:{tab:'utang',fid:f.id},schedule:{at,allowWhileIdle:true}})}});
L.sort((a,b)=>a.schedule.at-b.schedule.at);L.length=Math.min(L.length,200);
try{const dl=((await n.getDeliveredNotifications()).notifications||[]).map(x=>x.id);if(dl.length){const dead=new Set();D.faktur.filter(f=>sisaF(f)<=0).forEach(f=>{for(let k=2;k>=-30;k--)dead.add(nid(f.id+'|'+k))});const rm=dl.filter(id=>dead.has(id));if(rm.length)await n.removeDeliveredNotifications({notifications:rm.map(id=>({id}))})}}catch(e){}
for(let i=0;i<L.length;i+=25)await n.schedule({notifications:L.slice(i,i+25)});
localStorage.nids=JSON.stringify(L.map(x=>x.id));localStorage.nBusy='0';if(force)localStorage.nSafe='0'}catch(e){localStorage.nBusy='0'}}
async function nResched(){await schedN(true,true);render();toast('Jadwal reminder dibuat ulang')}
async function nTest(sec){const n=LN();if(!n)return toast('Notifikasi hanya jalan di APK, belum didukung di browser/PWA.');
if(!await nReady(true))return toast('Izin notifikasi ditolak. Aktifkan di Setelan HP > Aplikasi > Kelontong > Notifikasi.');
try{await n.schedule({notifications:[{id:sec?999002:999001,channelId:'nota',smallIcon:'ic_stat_kelontong',title:'🔔 Tes notifikasi Kelontong',body:sec?'Berhasil! Notif muncul walau layar mati / app ditutup.':'Notifikasi langsung berfungsi.',autoCancel:false,extra:{tab:'lap'},...(sec?{schedule:{at:new Date(Date.now()+sec*1000),allowWhileIdle:true}}:{})}]});toast(sec?'Matikan layar atau keluar dari app. Notif muncul sekitar '+sec+' detik lagi.':'Notifikasi dikirim.')}catch(e){toast('Tes gagal: '+(e.message||e))}}
async function nExact(){const n=LN();if(!n)return toast('Hanya tersedia di APK');try{const r=await n.checkExactNotificationSetting();if(r.exact_alarm=='granted')return toast('Alarm tepat waktu sudah diizinkan');await n.changeExactNotificationSetting()}catch(e){toast('Pengaturan ini tidak tersedia di HP kamu')}}
const notifH=()=>{let c=0;try{c=JSON.parse(localStorage.nids||'[]').length}catch(e){}return`<div class=card><b>🔔 Notifikasi Reminder Nota</b><p class=m>${LN()?(nCfg().on?'Reminder nota otomatis dikirim jam <b>'+nCfg().t.replace(':','.')+'</b> pada H-2, H-1, H+0, dan setiap hari selama nota terlambat, walau app ditutup. Terjadwal sekarang: <b>'+c+'</b> notifikasi.':'Reminder otomatis sedang <b>MATI</b>. Tidak ada notifikasi nota yang dikirim.'):'Notifikasi hanya aktif di aplikasi APK, bukan di browser.'}</p><div class=row style="align-items:center;margin-bottom:8px"><button class="${nCfg().on?'':'g'}" style="flex:1" onclick="nTog()">${nCfg().on?'✓ Reminder AKTIF':'Reminder MATI'}</button><input type=time value="${nCfg().t}" style="flex:1;min-height:44px;margin:0" onchange="nSetT(this.value)" aria-label="Jam reminder"></div><div class=row><button onclick="nTest(0)">Tes Sekarang</button><button class=g onclick="nTest(15)">Tes 15 detik<br><small>(matikan layar)</small></button></div>${localStorage.nSafe=='1'?'<p style="color:var(--bad);font-weight:700">⚠️ Penjadwalan notifikasi dijeda otomatis karena app sempat berhenti saat menjadwalkan. App tetap aman dipakai. Tekan Jadwalkan ulang untuk mencoba lagi.</p>':''}<div class=row style="margin-top:8px"><button class=g style="width:100%" onclick="nResched()">Jadwalkan ulang reminder</button></div><div class=row style="margin-top:8px"><button class=g style="width:100%" onclick="nExact()">Izinkan alarm tepat waktu</button></div><p class=m>Kalau notif telat/tidak muncul saat app ditutup: Setelan HP &gt; Aplikasi &gt; Kelontong &gt; Mulai otomatis = ON, dan Hemat baterai = Tanpa batasan.</p></div>`};
const nTap=()=>{const n=LN();if(!n)return;try{n.addListener('localNotificationActionPerformed',e=>{const x=e.notification&&e.notification.extra||{};if(x.fid&&D.faktur.some(f=>f.id==x.fid))pickF(x.fid);else if(x.tab&&V[x.tab])go(x.tab)})}catch(e){}};
const lap0=V.lap;V.lap=()=>notifH()+lap0();
(async()=>{try{db=await open();await load();render();if(localStorage.nBusy=='1'){localStorage.nBusy='0';localStorage.nSafe='1'}schedN(true);nTap();if(rem().length)toast('🔔 '+rem().length+' nota sales perlu perhatian (terlambat / jatuh tempo)')}catch(e){$('#v').innerHTML='<div class=e>Penyimpanan tidak tersedia: '+esc(e.message)+'</div>'}
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})})();
